import {
  StyledTooltipContainer,
  StyledTooltipContent,
  StyledTooltipHeader,
  StyledTooltipSubtitle,
  StyledTooltipText,
  StyledTooltipTitle,
} from './ChartTooltipContent.styles';

export interface ChartTooltipContentProps {
  title: string;
  subtitle?: string;
  text?: string;
  paddingLeft?: boolean;
}

export const ChartTooltipContent = ({
  title,
  subtitle,
  text,
  paddingLeft = true,
}: ChartTooltipContentProps) => {
  return (
    <StyledTooltipContainer>
      <StyledTooltipHeader>
        <StyledTooltipTitle>{title}</StyledTooltipTitle>
      </StyledTooltipHeader>
      <StyledTooltipContent $paddingLeft={paddingLeft}>
        {subtitle ? (
          <StyledTooltipSubtitle>{subtitle}</StyledTooltipSubtitle>
        ) : null}
        {text ? <StyledTooltipText>{text}</StyledTooltipText> : null}
      </StyledTooltipContent>
    </StyledTooltipContainer>
  );
};
